application.css:
* { box-sizing: border-box; }
:root { color: #172033; background: #f4f7fb; font-family: system-ui, -apple-system, "Segoe UI", sans-serif; line-height: 1.5; }
body { margin: 0; }
.container { width: min(100% - 2rem,  seventy-two-rem); max-width: 72rem; margin-inline: auto; }
.site-header { background: #173b67; color: #fff; padding: 3rem 0 2.5rem; }
.eyebrow { margin: 0 0 .35rem; color: #b9d9ff; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; font-size: .8rem; }
h1, h2 { line-height: 1.2; margin-top: 0; }
h1 { margin-bottom: .5rem; font-size: clamp(1.8rem, 4vw, 2.8rem); }
.intro { margin: 0; color: #e1edfc; }
.layout { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.15fr); gap: 1.5rem; padding-top: 2rem; padding-bottom: 3rem; }
.card { background: #fff; border: 1px solid #d8e0eb; border-radius: .75rem; padding: clamp(1.25rem, 3vw, 2rem); box-shadow: 0 .25rem 1rem rgba(23, 32, 51, .06); }
.card h2 { font-size: 1.35rem; margin-bottom: .5rem; }
.required-note { color: #536176; font-size: .9rem; margin: 0 0 1.25rem; }
.field { margin-bottom: 1rem; }
.form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; }
label { display: block; font-weight: 650; margin-bottom: .4rem; }
input, select { width: 100%; border: 1px solid #8b98aa; border-radius: .4rem; color: #172033; background: #fff; font: inherit; padding: .65rem .7rem; min-height: 2.75rem; }
input:focus, select:focus, button:focus { outline: 3px solid #f3b544; outline-offset: 2px; }
input:invalid:not(:placeholder-shown) { border-color: #a52a2a; }
.button { border: 0; border-radius: .4rem; cursor: pointer; font: inherit; font-weight: 700; padding: .72rem 1rem; }
.primary { background: #1769aa; color: #fff; width: 100%; margin-top: .35rem; }
.primary:hover { background: #125486; }
.form-message, .confirmation { border-radius: .4rem; padding: .7rem .85rem; margin-bottom: 1rem; }
.form-message { background: #fff0f0; color: #8b1e1e; border: 1px solid #e2a5a5; }
.confirmation { background: #eaf7ee; color: #155b2b; border: 1px solid #8ac49a; }
.booking-list { display: grid; gap: 1rem; }
.empty-state { color: #536176; margin: .5rem 0; }
.booking { border: 1px solid #cbd6e3; border-left: .3rem solid #1769aa; border-radius: .45rem; padding: 1rem; }
.booking h3 { margin: 0 0 .4rem; font-size: 1.1rem; }
.booking p { margin: .25rem 0; color: #3f4d61; }
.booking-actions { margin-top: .8rem; }
.cancel-button { background: #fff; color: #8b1e1e; border: 1px solid #b85b5b; }
.booking[data-status="cancelled"] { border-left-color: #687588; background: #f3f5f7; }
.booking[data-status="cancelled"] .cancel-button { display: none; }
.cancelled-label { color: #687588; font-weight: 700; }
@media (max-width: 700px) { .layout { grid-template-columns: 1fr; } .form-row { grid-template-columns: 1fr; gap: 0; } }

application.javascript:
const form = document.getElementById('booking-form');
const dateInput = document.getElementById('booking-date');
const list = document.getElementById('booking-list');
const emptyState = document.getElementById('empty-state');
const formMessage = document.getElementById('form-message');
const confirmation = document.getElementById('booking-confirmation');

function getToday() {
  const now = new Date();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  return `${now.getFullYear()}-${month}-${day}`;
}

function setMinimumDate() {
  dateInput.min = getToday();
}

function showMessage(element, message) {
  element.textContent = message;
  element.hidden = false;
}

function hideMessage(element) {
  element.hidden = true;
  element.textContent = '';
}

function formatDate(value) {
  const [year, month, day] = value.split('-').map(Number);
  return new Intl.DateTimeFormat(undefined, { dateStyle: 'long' }).format(new Date(year, month - 1, day));
}

function createBookingCard(booking) {
  const article = document.createElement('article');
  article.className = 'booking';
  article.dataset.testid = 'booking';
  article.dataset.status = 'active';

  const name = document.createElement('h3');
  name.dataset.testid = 'booking-name-display';
  name.textContent = booking.name;
  article.append(name);

  const details = document.createElement('p');
  details.textContent = `${booking.type} · ${formatDate(booking.date)} at ${booking.time}`;
  article.append(details);

  const email = document.createElement('p');
  email.textContent = booking.email;
  article.append(email);

  const actions = document.createElement('div');
  actions.className = 'booking-actions';
  const cancel = document.createElement('button');
  cancel.type = 'button';
  cancel.className = 'button cancel-button';
  cancel.dataset.testid = 'booking-cancel';
  cancel.textContent = 'Cancel booking';
  cancel.addEventListener('click', () => cancelBooking(article, cancel));
  actions.append(cancel);
  article.append(actions);
  return article;
}

function cancelBooking(article, button) {
  article.dataset.status = 'cancelled';
  const label = document.createElement('p');
  label.className = 'cancelled-label';
  label.textContent = 'Cancelled';
  article.append(label);
  button.disabled = true;
}

function handleSubmit(event) {
  event.preventDefault();
  hideMessage(formMessage);
  hideMessage(confirmation);
  if (!form.checkValidity()) {
    showMessage(formMessage, 'Please complete all required fields with valid information.');
    form.reportValidity();
    return;
  }
  if (dateInput.value < getToday()) {
    showMessage(formMessage, 'Please choose today or a future date.');
    dateInput.focus();
    return;
  }
  const data = new FormData(form);
  const booking = { name: data.get('name').trim(), email: data.get('email').trim(), date: data.get('date'), time: data.get('time'), type: data.get('type') };
  if (!booking.name || !booking.email || !booking.date || !booking.time || !booking.type) {
    showMessage(formMessage, 'Please complete all required fields.');
    return;
  }
  emptyState.hidden = true;
  list.append(createBookingCard(booking));
  showMessage(confirmation, `Booking confirmed for ${booking.name} on ${formatDate(booking.date)}.`);
  form.reset();
  setMinimumDate();
}

setMinimumDate();
form.addEventListener('submit', handleSubmit);
dateInput.addEventListener('input', () => hideMessage(formMessage));
